/**
 * Unit tests for CategoryPlot.removeDomainMarker.
 */
public class CategoryPlot_removeDomainMarker_TriageGen1Test {

    private CategoryPlot plot;
    private Marker mockMarker;
    private Marker anotherMarker;

    @Before
    public void setUp() throws Exception {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
        anotherMarker = mock(Marker.class);
    }

    /**
     * Helper method to inject markers into the private maps of CategoryPlot using reflection,
     * since the provided API doesn't show a public way to add markers for testing.
     */
    @SuppressWarnings("unchecked")
    private void injectMarkers(int index, Layer layer, ArrayList<Marker> markers) throws Exception {
        String fieldName = (layer == Layer.FOREGROUND) ? "foregroundDomainMarkers" : "backgroundDomainMarkers";
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        Map<Integer, ArrayList<Marker>> map = (Map<Integer, ArrayList<Marker>>) field.get(plot);
        if (map == null) {
            map = new HashMap<>();
            field.set(plot, map);
        }
        map.put(index, markers);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Success_Notify() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        injectMarkers(index, Layer.FOREGROUND, markers);

        // Note: fireChangeEvent is an internal method. 
        // In a real JFreeChart environment, we'd check if listeners were notified.
        // Here we test the boolean return and the logic flow.
        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Marker should be removed", result);
        assertTrue("Marker list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Success_NoNotify() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        injectMarkers(index, Layer.FOREGROUND, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, false);

        assertTrue("Marker should be removed", result);
        assertTrue("Marker list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Failure() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(anotherMarker);
        injectMarkers(index, Layer.FOREGROUND, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Marker should not be removed", result);
        assertEquals("Marker list should still contain the other marker", 1, markers.size());
    }

    @Test
    public void testRemoveDomainMarker_Background_Success_Notify() throws Exception {
        int index = 1;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        injectMarkers(index, Layer.BACKGROUND, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, true);

        assertTrue("Marker should be removed from background", result);
        assertTrue("Marker list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Background_Success_NoNotify() throws Exception {
        int index = 1;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        injectMarkers(index, Layer.BACKGROUND, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, false);

        assertTrue("Marker should be removed from background", result);
        assertTrue("Marker list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Background_Failure() throws Exception {
        int index = 1;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(anotherMarker);
        injectMarkers(index, Layer.BACKGROUND, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, true);

        assertFalse("Marker should not be removed from background", result);
        assertEquals("Marker list should still contain the other marker", 1, markers.size());
    }
}
